const raw = $json;
const d = (raw.body && raw.body.youtube_url !== undefined) ? raw.body : raw;
const youtube_url = (d.youtube_url || '').toString().trim();
const mode = (d.mode === 'checklist') ? 'checklist' : 'flowchart';
return [{ json: { youtube_url, mode } }];

const res = $input.first().json;
const apiError = res.error ? (typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error))) : null;
const parts = (res.candidates && res.candidates[0] && res.candidates[0].content && res.candidates[0].content.parts) || [];
const raw = (parts[0] && parts[0].text) ? parts[0].text : '{}';
let txt = raw.trim();
if (txt.startsWith('```')) { txt = txt.substring(txt.indexOf('\n') + 1); if (txt.endsWith('```')) txt = txt.slice(0, -3); txt = txt.trim(); }
let parsed = {};
try { parsed = JSON.parse(txt); } catch (e) { parsed = {}; }

let mermaid = (parsed.mermaid || '').toString().trim();
mermaid = mermaid
  .replace(/([A-Za-z0-9_]+)\[(?!")([^\]]*)\]/g, (m, id, label) => `${id}["${label.replace(/"/g, '\\"')}"]`)
  .replace(/([A-Za-z0-9_]+)\{(?!")([^}]*)\}/g, (m, id, label) => `${id}{"${label.replace(/"/g, '\\"')}"}`);
const ok = !apiError && /^(flowchart|graph)\s/i.test(mermaid);
const prep = $('Prepare Data').first().json;
return [{ json: {
  ok,
  youtube_url: prep.youtube_url,
  mode: 'flowchart',
  title: (parsed.title || 'Untitled').toString(),
  summary: (parsed.summary || '').toString(),
  mermaid: ok ? mermaid : null,
  checklist: null,
  status: 'ready',
  error_message: null
} }];

